<?php
declare(strict_types=1);

/**
 * Private CLI health check for cPanel operators.
 *
 * This command intentionally emits only component names and status. It never
 * prints configuration values, filesystem paths, SQL errors, or credentials.
 * Run it from cron or Terminal with TALYVANE_CONFIG pointing at the private
 * owner-only configuration generated by the installer.
 */

use Talyvane\Infrastructure\Database\ConnectionFactory;

$root = dirname(__DIR__);
require $root . '/bootstrap.php';

$options = getopt('', ['json']);
$json = array_key_exists('json', $options);
$checks = [];

$record = static function (string $name, bool $ok, string $detail) use (&$checks): void {
    $checks[] = ['check' => $name, 'status' => $ok ? 'ok' : 'failed', 'detail' => $detail];
};

$realConfig = false;
$configPath = getenv('TALYVANE_CONFIG');
if (!is_string($configPath) || $configPath === '' || is_link($configPath) ||
    !is_file($configPath) || !is_readable($configPath)) {
    $record('private_configuration', false, 'Private configuration is missing or unreadable.');
    $config = [];
} else {
    $realConfig = realpath($configPath);
    $permissions = $realConfig === false ? false : fileperms($realConfig);
    $safeConfig = $realConfig !== false && $permissions !== false &&
        (($permissions & 0077) === 0) && !is_link($realConfig);
    $record('private_configuration', $safeConfig, $safeConfig
        ? 'Configuration is readable and owner-only.'
        : 'Configuration must be canonical and owner-only (0600 recommended).');
    $config = $safeConfig ? require $realConfig : [];
    if (!is_array($config)) {
        $config = [];
        $record('configuration_shape', false, 'Configuration did not return an array.');
    } else {
        $record('configuration_shape', isset($config['app_key'], $config['database']) &&
            is_string($config['app_key']) && strlen($config['app_key']) >= 32 &&
            is_array($config['database']), 'Required application and database settings are present.');
    }
}

$requiredExtensions = ['pdo', 'pdo_mysql', 'openssl', 'fileinfo', 'json'];
foreach ($requiredExtensions as $extension) {
    $record('php_extension_' . $extension, extension_loaded($extension),
        extension_loaded($extension) ? 'Extension is loaded.' : 'Required PHP extension is not loaded.');
}
$record('php_version', PHP_VERSION_ID >= 80300,
    PHP_VERSION_ID >= 80300 ? 'PHP 8.3 or newer is active.' : 'PHP 8.3 or newer is required.');

$paths = is_array($config['paths'] ?? null) ? $config['paths'] : [];
$documentRootInput = $paths['document_root'] ?? null;
$documentRoot = is_string($documentRootInput) && $documentRootInput !== '' &&
    !is_link($documentRootInput) && is_dir($documentRootInput)
        ? realpath($documentRootInput)
        : false;
$record('document_root', $documentRoot !== false,
    $documentRoot !== false
        ? 'Configured public document root resolves to a real directory.'
        : 'Configured public document root is missing, invalid, or linked.');
$configOutsidePublicRoot = $realConfig !== false && $documentRoot !== false &&
    !str_starts_with($realConfig, rtrim($documentRoot, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR);
$record('configuration_outside_document_root', $configOutsidePublicRoot,
    $configOutsidePublicRoot
        ? 'Private configuration file is outside the public document root.'
        : 'Private configuration file is missing, invalid, or located under the public document root.');
foreach (['storage', 'logs', 'backups'] as $key) {
    $path = $paths[$key] ?? null;
    $private = is_string($path) && $path !== '' && !is_link($path) &&
        is_dir($path) && is_writable($path) ? realpath($path) : false;
    $mode = $private === false ? false : fileperms($private);
    $restricted = $mode !== false && (($mode & 0077) === 0) && (($mode & 0200) !== 0);
    $valid = $documentRoot !== false && $private !== false && $restricted &&
        $private !== $documentRoot &&
        !str_starts_with($private . DIRECTORY_SEPARATOR, rtrim($documentRoot, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR);
    $record('private_' . $key, $valid, $valid
        ? 'Directory exists, is owner-writable, has no group/world permissions, and is outside the configured document root.'
        : 'Directory is missing, not owner-writable, group/world-accessible, linked, or its public-root separation cannot be proven.');
}

$dbConfig = $config['database'] ?? null;
if (is_array($dbConfig) && isset($config['app_key']) && is_string($config['app_key'])) {
    try {
        $pdo = ConnectionFactory::mysql($dbConfig);
        $statement = $pdo->query('SELECT 1');
        $dbOk = $statement !== false && (int)$statement->fetchColumn() === 1;
        $record('database_connectivity', $dbOk, $dbOk
            ? 'Database connection and trivial query succeeded.'
            : 'Database connectivity check did not return the expected result.');
    } catch (Throwable) {
        $record('database_connectivity', false, 'Database connection failed; inspect private server logs.');
    }
} else {
    $record('database_connectivity', false, 'Database configuration is unavailable.');
}

$failed = count(array_filter($checks, static fn(array $check): bool => $check['status'] !== 'ok'));
$summary = [
    'application' => 'Talyvane Native PHP',
    'checked_at_utc' => gmdate('Y-m-d\TH:i:s\Z'),
    'status' => $failed === 0 ? 'ok' : 'degraded',
    'passed' => count($checks) - $failed,
    'failed' => $failed,
    'checks' => $checks,
];

if ($json) {
    fwrite(STDOUT, json_encode($summary, JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . PHP_EOL);
} else {
    fwrite(STDOUT, $summary['application'] . ' health: ' . strtoupper($summary['status']) . PHP_EOL);
    foreach ($checks as $check) {
        fwrite(STDOUT, sprintf("[%s] %s — %s\n", strtoupper($check['status']), $check['check'], $check['detail']));
    }
    fwrite(STDOUT, sprintf("Summary: %d passed, %d failed\n", $summary['passed'], $summary['failed']));
}

exit($failed === 0 ? 0 : 1);
